import csv, json

def rank_by(path, feat, reverse=True):
    out={}
    for r in csv.DictReader(open(path)):
        out.setdefault(r['query_id'],[]).append((float(r[feat]), r['doc_id']))
    return {q:[d for _,d in sorted(v, key=lambda x:x[0], reverse=reverse)] for q,v in out.items()}

sensor=[1 if abs(float(r['value']))>2 else 0 for r in csv.DictReader(open('data/sensor_test.csv'))]
network=[1 if float(r['src_bytes'])>1000 and float(r['dst_bytes'])>1000 else 0 for r in csv.DictReader(open('data/network_test.csv'))]
results={
 'sensor':sensor,
 'network':network,
 'movie_rank':rank_by('data/movie_test.csv','year'),
 'news_rank':rank_by('data/news_test.csv','length'),
 'both_rank':rank_by('data/both_test.csv','score'),
}
json.dump(results, open('results.json','w'), indent=1)
print('sensor flagged',sum(sensor),'network flagged',sum(network))
print('movie q1',results['movie_rank']['q1'])
print('news nq1',results['news_rank']['nq1'])
print('both bq1',results['both_rank']['bq1'])
EOF
