{"command": "python3 -c "
import json,csv
r=json.load(open('results.json'))
assert set(r)=={'sensor','network','movie_rank','news_rank','both_rank'}
assert len(r['sensor'])==100 and len(r['network'])==150
for key,f in [('movie_rank','data/movie_test.csv'),('news_rank','data/news_test.csv'),('both_rank','data/both_test.csv')]:
    rows=list(csv.DictReader(open(f)))
    from collections import defaultdict
    d=defaultdict(list)
    for x in rows: d[x['query_id']].append(x['doc_id'])
    assert set(r[key])==set(d), (key)
    for q in d: assert sorted(r[key][q])==sorted(d[q]), (key,q)
print('schema OK')
""}

